// moderation code.
type ActionKind string

// ActionTargetType defines model for ActionTargetType.
type ActionTargetType string

// Address defines model for Address.
type Address struct {
	// Area District / community, e.g. Al Barsha 1.
	Area     *string `json:"area,omitempty"`
	Building *string `json:"building,omitempty"`
	City     string  `json:"city"`

	// Country Examples: AE, SA
	Country   string    `json:"country"`
	CreatedAt time.Time `json:"created_at"`

	// Emirate Emirate (UAE) or region (KSA).
	Emirate   *string            `json:"emirate,omitempty"`
	Flat      *string            `json:"flat,omitempty"`
	Id        openapi_types.UUID `json:"id"`
	IsDefault *bool              `json:"is_default,omitempty"`

	// Label Examples: Home, Office
	Label          string   `json:"label"`
	Landmark       *string  `json:"landmark,omitempty"`
	Notes          *string  `json:"notes,omitempty"`
	Point          GeoPoint `json:"point"`
	RecipientName  *string  `json:"recipient_name,omitempty"`
	RecipientPhone *string  `json:"recipient_phone,omitempty"`
	Street         *string  `json:"street,omitempty"`
}

// AddressInput GCC addressing is landmark-based. A postcode-driven form fails here — `landmark`
